const now = new Date();
const dayOfWeek = now.getDay();
const startDate = new Date('2026-05-12');
const diffDays = Math.floor((now - startDate) / (1000*60*60*24));
const weekNum = Math.floor(diffDays / 7) + 1;
const dayNum = (dayOfWeek + 6) % 7;
const days = ['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];

const curriculum = {
  alegria: {
    1: {
      1: { theme: 'n8n — Interface & 1er workflow', objectif: 'Comprendre interface n8n, créer premier workflow', etapes: ['Ouvrir n8n (10.30.20.2)', 'Découvrir Canvas, nodes, connexions', 'Créer un trigger Manuel', 'Ajouter un node Telegram', 'Exécuter et voir le résultat'], livrable: 'Workflow Bonjour monde fonctionnel' },
      2: { theme: 'n8n — Scheduler & automatisation', objectif: 'Déclencher automatiquement un workflow', etapes: ['Node Scheduler : 6h45 chaque matin', 'Node Set : message variable', 'Node IF : condition simple', 'Envoyer message différent selon le jour', 'Tester'], livrable: 'Workflow Bon matin automatique' },
      3: { theme: 'n8n — HTTP Request & APIs', objectif: 'Appeler une API externe et utiliser les données', etapes: ['Explication API simple', 'Node HTTP Request GET', 'API météo wttr.in', 'Extraire les données JSON', 'Formater et envoyer'], livrable: 'Workflow Météo du jour' },
      4: { theme: 'n8n — Webhook & formulaire', objectif: 'Recevoir données dun formulaire et les traiter', etapes: ['Node Webhook : créer URL', 'Formulaire simple (Tally)', 'Extraire les champs', 'Sauvegarder dans Notion', 'Confirmation automatique'], livrable: 'Formulaire → n8n → Notion + confirmation' },
      5: { theme: 'PROJET S1 — Workflow complet', objectif: 'Assembler tout ce qui a été appris', etapes: ['Choisir un cas dusage', 'Dessiner sur papier', 'Implémenter en n8n (30 min)', 'Tester et corriger (20 min)', 'Présenter à voix haute (10 min)'], livrable: 'Mini-projet S1 fonctionnel' }
    },
    2: {
      1: { theme: 'Claude API — Introduction', objectif: 'Premier appel IA dans n8n', etapes: ['Créer compte Anthropic', 'HTTP Request vers api.anthropic.com', 'Envoyer un message simple', 'Voir la réponse', 'Modifier le prompt'], livrable: 'Premier appel Claude API' },
      2: { theme: 'Claude API — Générer du texte', objectif: 'Générer emails et résumés automatiquement', etapes: ['System prompt : rôle de lIA', 'User prompt : demande précise', 'Générer un email professionnel', 'Résumer un texte long', 'Varier le ton'], livrable: 'Workflow résumé automatique' },
      3: { theme: 'Claude API — Analyser des données', objectif: 'Envoyer un fichier et obtenir une analyse', etapes: ['CSV → texte pour Claude', 'Demander les 3 points importants', 'Structurer la réponse', 'Appliquer sur vraie donnée', 'Sauvegarder dans Notion'], livrable: 'Workflow analyse données → Notion' },
      4: { theme: 'Claude API — Créer du contenu', objectif: 'Générer posts LinkedIn automatiquement', etapes: ['Prompt post LinkedIn', 'Ajouter émojis et structure', 'Varier le sujet', 'Workflow thème → post prêt', 'Programmer à heure fixe'], livrable: 'Workflow générateur de posts LinkedIn' },
      5: { theme: 'PROJET S2 — Agent IA simple', objectif: 'Premier agent IA qui répond à des questions', etapes: ['Définir le cas dusage', 'Rédiger le system prompt', 'Créer le workflow complet', 'Tester avec 5 questions', 'Présenter le résultat'], livrable: 'Agent IA fonctionnel' }
    }
  }
};

const week = Math.min(weekNum, 4);
const day = Math.min(dayNum + 1, 5);
const session = curriculum.alegria?.[week]?.[day] || { theme: 'Révision libre', objectif: 'Consolider les acquis', etapes: ['Refaire un workflow de la semaine passée', 'Identifier les points flous', 'Les corriger'], livrable: 'Workflow amélioré' };

return [{ json: { weekNum, dayNum: day, dayName: days[dayOfWeek], session, type: 'alegria' } }];

const data = $input.first().json;
const s = data.session;
const etapes = s.etapes.map((e, i) => `${i+1}. ${e}`).join('\n');

const message = `🌅 *BRIEF ALEGRIA — Séance du jour*
━━━━━━━━━━━━━━━━━━━━━
📅 *${data.dayName}* — Semaine ${data.weekNum}
🎯 *Thème :* ${s.theme}

*Objectif de la session (2h) :*
${s.objectif}

*📋 Étapes à suivre :*
${etapes}

*✅ Livrable attendu :*
${s.livrable}

━━━━━━━━━━━━━━━━━━━━━
💪 *Bonne session ! Chaque ligne de workflow est un pas vers l'autonomie.*
⏰ Rappel : 6h00 sport → 6h30 cours`;

return [{ json: { message, session: s } }];

const now = new Date();
const dayOfWeek = now.getDay();
const startDate = new Date('2026-05-12');
const diffDays = Math.floor((now - startDate) / (1000*60*60*24));
const weekNum = Math.floor(diffDays / 7) + 1;
const dayNum = (dayOfWeek + 6) % 7;
const days = ['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];

const theoProgram = {
  1: {
    1: 'n8n Avancé — Expressions & JSON : maîtriser les expressions {{ }}, fonctions JS inline, manipulation JSON complexe',
    2: 'APIs Avancées & Auth : Bearer Token, OAuth2, pagination automatique, rate limiting, gestion derreurs',
    3: 'Sub-workflows & Architecture : modules réutilisables, exécutions parallèles, webhooks sécurisés',
    4: 'Workflow Professionnel : rapport réseau automatisé depuis CatC/WLC, PDF, alertes Slack',
    5: 'LIVRABLE S1 : finaliser, documenter, packager, chiffrer, démo 5 min'
  },
  2: {
    1: 'Agents IA — Architecture & Mémoire : system prompt avancé, mémoire contextuelle, structured output JSON',
    2: 'Agent Qualification Leads NEXOR : email → extraire → scorer → Notion CRM → réponse auto',
    3: 'Agent Support IT Réseau : alerte SolarWinds → diagnostic → ticket Notion → escalade Slack',
    4: 'RAG Basique : base de connaissances Claude + documentation Cisco, 10 questions réelles',
    5: 'LIVRABLE S2 : agent IA documenté + démo client 10 min + prix estimé'
  },
  3: {
    1: 'Make Expert — Routeurs & Iterators : router, iterator, aggregator, error handling avancé',
    2: 'Architecture Multi-outils : n8n vs Make, CRM automatisé Make + Airtable + Gmail',
    3: 'PROJET CLIENT NEXOR Jour 1 : architecture + 30% implémenté',
    4: 'PROJET CLIENT NEXOR Jour 2 : 80% + documentation technique',
    5: 'LIVRABLE S3 : projet livré + facture NEXOR émise'
  },
  4: {
    1: 'Bubble.io Avancé — API Connector : Claude API + n8n webhook + données live',
    2: 'WifiAudit AI Interface : upload + scores RF + graphiques + export PDF',
    3: 'Stripe & Abonnements dans Bubble : 3 plans + gestion abonnements + webhook',
    4: 'Industrialisation : template projet + grille tarification + contrat type + portfolio',
    5: 'LIVRABLE FINAL : démo autonome 20 min + rapport évaluation complet'
  }
};

const week = Math.min(weekNum, 4);
const day = Math.min(dayNum + 1, 5);
const theme = theoProgram[week]?.[day] || 'Révision et approfondissement — refaire un livrable de la semaine';

return [{ json: { weekNum, dayName: days[dayOfWeek], theme, day, type: 'theo' } }];

const data = $input.first().json;
const message = `🌙 *BRIEF THÉO — Séance du soir*
━━━━━━━━━━━━━━━━━━━━━
📅 *${data.dayName}* — Semaine ${data.weekNum}

*🎯 Objectif ce soir (3h) :*
${data.theme}

*⚙️ Rappel méthode :*
• 20h00 - 20h15 : Révision de la veille (5 questions)
• 20h15 - 22h00 : Nouvelle notion + construction
• 22h00 - 22h45 : Livrable réel à terminer
• 22h45 - 23h00 : Objectif pour demain

*📌 Règle d'or :* Chaque notion = construire quelque chose de fonctionnel. Pas de théorie sans pratique.

━━━━━━━━━━━━━━━━━━━━━
🔥 *C'est en soirée qu'on forge les compétences qui feront tourner NEXOR.*`;

return [{ json: { message } }];

const now = new Date();
const isWeekend = now.getDay() === 6 ? 'samedi' : 'dimanche';
const startDate = new Date('2026-05-12');
const weekNum = Math.floor((now - startDate) / (1000*60*60*24*7)) + 1;

const weekendPlan = {
  samedi: {
    matin: ['Bilan semaine passée (score /10)', '30 contacts LinkedIn personnalisés (DSI/DG)', '5 emails de prospection qualifiés', 'Préparer les cours Alegria et Théo semaine suivante'],
    soir: ['Construction NoCode perso : reproduire les workflows de la semaine', 'Avancer sur WifiAudit AI ou projet NEXOR', 'Créer 2 posts LinkedIn pour la semaine']
  },
  dimanche: {
    matin: ['Deep work NoCode : apprendre en construisant', 'Développement WifiAudit AI (endpoint ou interface)', 'Si prospect disponible : call découverte'],
    soir: ['Bilan semaine complète + plan semaine suivante', 'Mise à jour trésorerie ORNET', 'Livraison ou amélioration projets en cours', 'Relances prospects + pipeline NEXOR']
  }
};

const plan = weekendPlan[isWeekend];
const matin = plan.matin.map((t,i) => `${i+1}. ${t}`).join('\n');
const soir = plan.soir.map((t,i) => `${i+1}. ${t}`).join('\n');

const message = `🚀 *BRIEF WEEKEND — Semaine ${weekNum}*
━━━━━━━━━━━━━━━━━━━━━
📅 *${isWeekend.charAt(0).toUpperCase() + isWeekend.slice(1)} — Jour NEXOR*

*🌅 8h00 – 12h00 (priorité) :*
${matin}

*🌙 19h00 – 23h00 (construction) :*
${soir}

━━━━━━━━━━━━━━━━━━━━━
*📊 Rappel objectifs :*
• 1 contrat NEXOR signé avant fin du mois
• WifiAudit AI : premier client payant
• Formation : 0 session manquée

💪 *Pas de weekend. Que des opportunités.*`;

return [{ json: { message } }];

